<?php
namespace qqworld_collector\module\cloud_storage; use qqworld_collector\lib; class compatibility extends lib { var $priority = 99999999; public function init() { switch ($this->options->cloud_storage_compatibility_mode) { case 1: add_filter( 'image_send_to_editor',array($this, 'image_send_to_editor'), $this->priority, 8 ); add_filter( 'image_downsize', array($this, 'image_downsize'), $this->priority, 3 ); add_filter( 'wp_get_attachment_url', array($this, 'wp_get_attachment_url'), $this->priority, 2 ); add_filter( 'wp_get_attachment_image_src', array($this, 'wp_get_attachment_image_src'), $this->priority, 4 ); add_filter( 'wp_calculate_image_srcset', array($this, 'wp_calculate_image_srcset'), $this->priority, 5); add_filter( 'wp_calculate_image_srcset_meta', array($this, 'wp_calculate_image_srcset_meta'), $this->priority, 4 ); break; case 0: default: add_action( 'wp', array($this, 'template_redirect') ); break; } } public function common_bulk_parser($html) { if ( ($this->options->cloud_storage_compatibility_prefix && strstr($html, $this->options->cloud_storage_compatibility_prefix) === false) || $this->options->cloud_storage_compatibility_suffix && strstr($html, $this->options->cloud_storage_compatibility_suffix) === false) { $preg = preg_match_all('/'.$this->encode_pattern(home_url()).'[^>^<]*?\.(jpg|jpeg|png|gif)/i', $html, $matches); if ($preg) { $patterns = array(); $replacements = array(); foreach ($matches[0] as $index => $match) { $patterns[] = $match; $replacements[] = $this->options->cloud_storage_compatibility_prefix . $match . $this->options->cloud_storage_compatibility_suffix; } $html = str_replace($patterns, $replacements, $html); } } return $html; } public function template_redirect() { ob_start(array($this, 'replace')); } public function replace($buffer) { $buffer = $this->common_parse_url($buffer); $buffer = $this->common_bulk_parser($buffer); return $buffer; } public function common_parse_url($content) { if ($this->options->cloud_storage_compatibility_wrong_url) { if (strstr($this->options->cloud_storage_compatibility_wrong_url, '(*)') !== false) { $patterns = $this->encode_pattern($this->options->cloud_storage_compatibility_wrong_url); $patterns = str_replace('\(\*\)', 'https?:\/\/(www\.)?', $patterns); $content = preg_replace('/'.$patterns.'/i', $this->options->cloud_storage_compatibility_correct_url, $content); } else { $content = str_replace($this->options->cloud_storage_compatibility_wrong_url, $this->options->cloud_storage_compatibility_correct_url, $content); } } return $content; } public function common_parser($url) { $url = $this->common_parse_url($url); if (($this->options->cloud_storage_compatibility_prefix && strstr($url, $this->options->cloud_storage_compatibility_prefix) === false) || ($this->options->cloud_storage_compatibility_suffix && strstr($url, $this->options->cloud_storage_compatibility_suffix) === false)) $url = $this->options->cloud_storage_compatibility_prefix . $url . $this->options->cloud_storage_compatibility_suffix; return $url; } public function image_send_to_editor($html, $id, $caption, $title, $align, $url, $size, $alt) { if ($this->options->cloud_storage_compatibility_wrong_url) $html = str_replace($this->options->cloud_storage_compatibility_wrong_url, $this->options->cloud_storage_compatibility_correct_url, $html); if ($this->options->cloud_storage_compatibility_prefix || $this->options->cloud_storage_compatibility_suffix) $html = $this->common_bulk_parser($html); return $html; } public function image_downsize($downsize, $id, $size) { if ($downsize && is_array($downsize)) { $downsize[0] = $this->common_parser($downsize[0]); } return $id ? $downsize : false; } public function wp_get_attachment_url($url, $post_id) { $url = $this->common_parser($url); return $url; } public function wp_get_attachment_image_src($image, $attachment_id, $size, $icon) { if ($image && is_array($image)) { $image[0] = $this->common_parser($image[0]); } return $image; } public function wp_calculate_image_srcset($sources, $size_array, $image_src, $image_meta, $attachment_id) { if (count($sources)) foreach ($sources as &$source) { $source['url'] = $this->common_parser($source['url']); } return $sources; } public function wp_calculate_image_srcset_meta($image_meta, $size_array, $image_src, $attachment_id) { $image_meta['file'] = $this->common_parser($image_meta['file']); return $image_meta; } } ?>